#!/bin/sh
# Build the WebAssembly core (core.c) into core-wasm.js (base64: engine.js loads it synchronously in a worker and in Node).
# Then: node tools/check_rules.js (the rules: the same as engine.js) and node tools/check_wasm.js (the same searches as the JS).
# Two builds in core-wasm.js: LT_WASM with wasm SIMD (-msimd128), LT_WASM0 without it for a browser that has no SIMD (engine.js
# takes the first that compiles). core_mt.wasm: the same core for the threads of the page's pool (shared/mtengine.js; the lead
# engine.js?…&mt=1, the helpers mt-helper.js): -DMT — thread-local search state, one lockless table, Praline's Young Brothers
# Wait (shared/praline/). With SIMD only (every browser with shared memory and threads has it).
cd "$(dirname "$0")/.."
W="clang --target=wasm32 -nostdlib -fno-builtin -O3 -w -Wl,--no-entry -Wl,--export-dynamic -Wl,--allow-undefined -Wl,-z,stack-size=8388608 -Wl,--initial-memory=67108864"
$W -msimd128 -o /tmp/latrunculi-core-simd.wasm core.c || exit 1
$W -o /tmp/latrunculi-core.wasm core.c || exit 1
node -e "const f=require('fs'),a=f.readFileSync('/tmp/latrunculi-core-simd.wasm'),b=f.readFileSync('/tmp/latrunculi-core.wasm');f.writeFileSync('core-wasm.js','// generated by tools/build-core.sh from core.c — do not edit\nself.LT_WASM=\''+a.toString('base64')+'\';\nself.LT_WASM0=\''+b.toString('base64')+'\';\n');console.log('core-wasm.js', a.length, '+', b.length, 'bytes of wasm')"
clang --target=wasm32 -O3 -msimd128 -matomics -mbulk-memory -DMT -nostdlib -fno-builtin -w -Wl,--no-entry -Wl,--export-dynamic -Wl,--shared-memory -Wl,--import-memory -Wl,--max-memory=1073741824 -o core_mt.wasm core.c || exit 1
echo "core_mt.wasm $(wc -c < core_mt.wasm) bytes"
